  const ensureSceneRoute = (): string | null => {
    if (routeDisposers.length > 0) return '/dsh-cad/scene'
    const scope = ctx as { get?: (name: string) => unknown }
    const server = (scope.get?.('webServer') ?? scope.get?.('httpServer')) as
