ileSync('src/modeling/occtts-adapter.cjs','lib/modeling/occtts-adapter.cjs'); fs.copyFileSync('src/modeling/cadorange-bridge.cjs','lib/modeling/cadorange-bridge.cjs'); fs.copyFileSync('src/modeling/cadorange-adapter.cjs','lib/modeling/cadorange-adapter.cjs'); for (const part of ['bracket','flange','shaft']) fs.copyFileSync('assets/demo-'+part+'.brep','lib/demo-'+part+'.brep')\\\"\",\n    \"watch\": \"tsc -p tsconfig.json --watch & node esbuild.client.mjs --watch\",\n    \"test\": \"vitest run --no-file-parallelism\",\n    \"test:watch\": \"vitest\",\n    \"chart\": \"node scripts/gen-downloads-chart.mjs\"\n  },\n  \"dependencies\": {\n    \"ansatz-wasm\": \"^0.2.0\",\n    \"cadorange\": \"^0.10.0\",\n    \"dxf-parser\": \"^1.1.2\",\n    \"occt-import-js\": \"^0.0.23\",\n    \"occt.ts\": \"^1.1.0\",\n    \"three\": \"^0.185.1\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1-rc.1\",\n    \"@deepseek-ai/dsh-tools\": \">=0.0.1-rc.1\",\n    \"react\": \"^18.2.0\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/dsh-tools\": \"^0.1.7-rc.2\",\n    \"@types/node\": \"^22.10.0\",\n    \"@types/react\": \"^18.3.1\",\n    \"esbuild\": \"^0.28.2\",\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"^18.3.1\",\n    \"typescript\": \"^5.7.0\",\n    \"vitest\": \"^4.1.10\"\n  }\n}\n"
