      "path": "src/tools/cad-view.ts",
      "content": "/**\n * The `cad_view` tool: load a CAD file, convert it to a renderable scene, and\n * project presentation metadata the Web UI card renders as a 3D/2D viewer.\n */\nimport { basename } from 'node:path'\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nimport type { ToolDefinition } from '@deepseek-ai/dsh-tools'\nimport { detectFormat, is3DFormat } from '../convert/detect.js'\nimport { convert } from '../convert/index.js'\nimport { sceneStats } from '../types.js'\nimport type { SceneStore } from '../store.js'\nimport { loadCadFile, resolveSessionPath } from './util.js'\n\nexport interface CadViewToolDeps {\n  store: SceneStore\n  workspaceRoot: string\n  /** Idempotent lazy route registration; returns the scene URL base or null. */\n  ensureSceneRoute: () => string | null\n}\n\nfunction formatBounds(stats: ReturnType<typeof sceneStats>): string {\n  if (stats.boundsMin === undefined || stats.boundsMax === undefined) return ''\n  const min = stats.boundsMin\n  const max = stats.boundsMax\n  return `bounds [${min.map((v) => v.toFixed(2)).join(', ')}] → [${max.map((v) => v.toFixed(2)).join(', ')}]`\n}\n\n/** Build the cad_view tool definition over the scene store. */\nexport function createCadViewTool(deps: CadViewToolDeps): ToolDefinition {\n  return defineTool({\n    name: 'cad_view',\n    description:\n      'Open a CAD file in the interactive viewer embedded in the chat UI. ' +\n      '3D: STL, OBJ, STEP (.step/.stp), IGES (.iges/.igs), BREP, DCPRT (.dcprt native part document). 2D: DXF, SVG. ' +\n      'The card shows the geometry (orbit/zoom for 3D, pan/zoom for 2D) plus a geometry summary. ' +\n      'Use it whenever the user wants to see, inspect, or verify CAD geometry; the returned summary carries bounds and counts.',\n    parameters: {\n      path: {\n        type: 'string',\n        required: true,\n        description: 'Path to the CAD file, absolute or relative to the workspace root.',\n      },\n    },\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        properties: {\n          viewId: { type: 'string', required: true, description: 'Viewer scene id.' },\n          kind: { type: 'string', enum: ['3d', '2d'] as const, required: true, description: 'Viewer kind.' },\n          format: { type: 'string', required: true, description: 'Detected source format.' },\n          file: { type: 'string', required: true, description: 'Resolved file path.' },\n          sceneUrl: { type: 'string', description: 'Same-origin JSON scene URL (web compositions only).' },\n          triangles: { type: 'number', description: 'Total triangle count (3D).' },\n          meshes: { type: 'number', description: 'Part count (3D).' },\n          entities: { type: 'number', description: 'Drawing entity count (2D).' },\n        },\n      },\n      render: (_args, value) => {\n        const lines = [`CAD viewer: ${value.file} (${value.format.toUpperCase()}, ${value.kind.toUpperCase()})`]\n        if (value.kind === '3d') {\n          lines.push(`${value.meshes ?? 0} part(s), ${value.triangles ?? 0} triangles`)\n        } else {\n          lines.push(`${value.entities ?? 0} entities`)\n        }\n        return [{ type: 'text', text: lines.join('\\n') }]\n      },\n      presentationMeta: (_args, value) => ({\n        viewId: value.viewId,\n        kind: value.kind,\n        format: value.format,\n        file: basename(value.file),\n        ...(value.sceneUrl === undefined ? {} : { sceneUrl: value.sceneUrl }),\n        title: `${basename(value.file)} · ${value.format.toUpperCase()}`,\n        stats: {\n          ...(value.meshes === undefined ? {} : { meshes: value.meshes }),\n          ...(value.triangles === undefined ? {} : { triangles: value.triangles }),\n          ...(value.entities === undefined ? {} : { entities: value.entities }),\n        },\n      }),\n    },\n    timeoutMs: 180_000,\n    isConcurrencySafe: () => true,\n    async execute(args, exec: unknown) {\n      const resolved = resolveSessionPath(args.path, exec, deps.workspaceRoot)\n      const name = basename(resolved)\n      const format = detectFormat(name)\n      if (format === null) {\n        throw new Error(\n          `unsupported CAD format: ${name} — supported extensions are .stl .obj .step .stp .iges .igs .brep .dcprt .dxf .svg`,\n        )\n      }\n      const buffer = await loadCadFile(resolved)\n      const scene = await convert(buffer, format, name)\n      const stats = sceneStats(scene)\n      const viewId = await deps.store.put(scene)\n      const kind: '3d' | '2d' = is3DFormat(format) ? '3d' : '2d'\n      const sceneUrlBase = deps.ensureSceneRoute()\n      // Optional fields spread conditionally: an explicit undefined value\n      // would fail the registry's lossless-JSON output validation.\n      return {\n        viewId,\n        kind,\n        format,\n        file: resolved,\n        ...(sceneUrlBase === null ? {} : { sceneUrl: `${sceneUrlBase}/${viewId}` }),\n        ...(stats.triangles === undefined ? {} : { triangles: stats.triangles }),\n        ...(stats.meshes === undefined ? {} : { meshes: stats.meshes }),\n        ...(stats.entities === undefined ? {} : { entities: stats.entities }),\n      }\n    },\n    presentCall: (args) => ({\n      card: 'generic',\n      title: `CAD view ${args.path}`,\n      kind: 'other',\n    }),\n    presentResult: (args, result) => ({\n      card: 'generic',\n      title: result.isError\n        ? `CAD view ${args.path} failed`\n        : `CAD viewer: ${args.path}`,\n    }),\n  }) as ToolDefinition\n}\n"
    },
    {
      "path": "client/index.tsx",
      "content": "/**\n * dsh-cad client plugin:\n * - compact one-line rows for the cad_* tool calls in the chat flow (the\n *   resident panel is the single CAD display area; every settled row also\n *   feeds the latest-CAD memory behind the panel's fallback channel);\n * - the resident CAD display panel, mounted as a host rightbar PANE through\n *   the sidebar-right tab system (dsh ≥0.2.x — the host's docking kit owns\n *   width/collapse/float/fullscreen and remembers the open tab per session).\n *   Hosts without the pane system mount no panel.\n */\nimport type { CadCardProps } from './card.js'\nimport { CadCallRow } from './card.js'\nimport { mountCadPanel } from './pane.js'\nimport type { SessionsLike } from './sidepanel.js'\n\nexport const inject = ['slots']\n\ninterface SlotsService {\n  inject(slot: string, register: () => unknown): unknown\n  register(options: { name: string; key?: string; id?: string; label?: string; priority?: number }, component: (props: never) => JSX.Element): unknown\n}\n\ninterface ClientContext {\n  slots: SlotsService\n  get?: (name: string) => unknown\n}\n\n/** Every tool whose chat card is the CAD viewport. */\nconst CAD_TOOL_KEYS = [\n  'cad_view',\n  'cad_create_prim',\n  'cad_extrude_profile',\n  'cad_revolve',\n  'cad_chamfer',\n  'cad_shell',\n  'cad_draft',\n  'cad_pattern',\n  'cad_loft',\n  'cad_sweep',\n  'cad_boolean',\n  'cad_fillet',\n  'cad_transform',\n  'cad_export',\n  'cad_delete',\n  'cad_volume',\n  'cad_freecad',\n  'cad_image_profile',\n  'cad_drawing',\n  'cad_assembly_insert',\n  'cad_assembly_move',\n  'cad_assembly_remove',\n  'cad_doc_open',\n  'cad_constraint',\n  'cad_solve',\n  'cad_motion',\n]\n\nexport function apply(ctx: ClientContext): void {\n  // Entry-crash supervision (the slots' onEntryError seam): render-time\n  // failures abdicate an entry silently, so mirror them on the document —\n  // the CadErrorBoundary data-cad-err pattern — for diagnosable drift.\n  const supervised = ctx.slots as typeof ctx.slots & {\n    onEntryError?: (fn: (key: string, entry: unknown, error: unknown, info: { abdicated: boolean }) => void) => () => void\n  }\n  supervised.onEntryError?.((key, _entry, error, info) => {\n    try {\n      document.documentElement.setAttribute(\n        'data-cad-slot-crash',\n        `${key}:${String(error instanceof Error ? error.message : error).slice(0, 160)}:abd=${String(info.abdicated)}`,\n      )\n    } catch { /* non-DOM host */ }\n  })\n\n  // Chat tool rows: keyed toolview entries (a keyed hit replaces the generic\n  // row). `locale` tags the entry for the conversation namespace's `t` seat.\n  for (const key of CAD_TOOL_KEYS) {\n    ctx.slots.inject('tool.call.toolview', () =>\n      ctx.slots.register({ name: 'tool.call.toolview', key, locale: 'conversation' }, CadCallRow as unknown as (props: never) => JSX.Element),\n    )\n  }\n\n  // The resident CAD panel. `ctx.get(name)` is the optional-service\n  // convention. The host rightbar pane (sidebar-right tab system): layout,\n  // collapse, float, fullscreen, and per-session open state are the host's,\n  // with zero self-measured positioning; the service lookup retries over the\n  // first ~1.6s because this plugin activates before the sidebar-right\n  // package provides it, and hosts without the pane system mount no panel.\n  // (`ctx.get('sessions')` is the live conversation feed behind the panel's\n  // model tracking; without it the panel falls back to the card-fed\n  // latest-CAD memory. Direct `ctx.sessions` access would throw — the\n  // property requires declaring an inject.)\n  const sessions = ctx.get?.('sessions') as SessionsLike | undefined\n  mountCadPanel(ctx, sessions)\n}\n"
    },
    {
      "path": "src/index.ts",
      "content": "/**\n * dsh-cad host plugin: registers the `cad_view` / `cad_info` tools and the\n * same-origin scene route on the Web composition's shared HTTP server.\n *\n * The HTTP server is an optional backend: fibers may activate before the web\n * composition defines it (and headless never does), so the route registers\n * lazily at first `cad_view` execution — the platform's use-time-resolution\n * idiom rather than a hard inject.\n */\nimport type { Context } from '@deepseek-ai/cordis'\nimport { SceneStore } from './store.js'\nimport { BinarySceneStore } from './modeling/bin-store.js'\nimport { DocumentRegistry } from './modeling/registry.js'\nimport { registerSceneRoute, registerBinRoute, registerDemoRoute, registerDocsRoute, registerDocsDeleteRoute, registerAssemblyRoute, registerFeatureTreeRoute } from './routes.js'\nimport type { SceneRoute } from './routes.js'\nimport { createCadViewTool } from './tools/cad-view.js'\nimport { createCadInfoTool } from './tools/cad-info.js'\nimport { createModelTools } from './tools/cad-model.js'\nimport { createFreeCadTool } from './tools/cad-freecad.js'\nimport { createFusionTool } from './tools/cad-fusion.js'\nimport { createOnshapeTool } from './tools/cad-onshape.js'\nimport { createCadImageTool } from './tools/cad-image.js'\nimport { createCadScriptTool } from './tools/cad-script.js'\n\nexport const name = 'dsh-cad'\n\n/** Hard dependencies: the tool registry. */\nexport const inject = ['tools']\n\nexport interface Config {\n  /** Directory the scene spill store uses; defaults to the workspace root. */\n  root?: string\n}\n\nexport function apply(ctx: Context, config: Config = {}): void {\n  const root = config.root ?? process.cwd()\n  const store = new SceneStore(root)\n  const binStore = new BinarySceneStore(root)\n  const registry = new DocumentRegistry(process.cwd())\n  const workspaceRoot = process.cwd()\n\n  // The routes live on the host's shared webServer, which outlives this\n  // plugin instance: hosts that hot-reload (the desktop runtime) re-run\n  // apply() in the same process, and the server throws on duplicate\n  // (kind, path). Every register disposer must therefore run on disposal —\n  // leaking them makes the next apply() throw and breaks every\n  // viewer-dependent tool call until a process restart.\n  let routeDisposers: Array<() => void> = []\n  /** Idempotently register the scene routes; returns the JSON base or null. */\n  const ensureSceneRoute = (): string | null => {\n    if (routeDisposers.length > 0) return '/dsh-cad/scene'\n    const scope = ctx as { get?: (name: string) => unknown }\n    const server = (scope.get?.('webServer') ?? scope.get?.('httpServer')) as\n      | { register: (route: SceneRoute) => () => void }\n      | undefined\n    if (server === undefined) return null\n    const pending: Array<() => void> = []\n    try {\n      pending.push(registerSceneRoute(server, store))\n      pending.push(registerBinRoute(server, binStore))\n      pending.push(registerDemoRoute(server))\n      pending.push(registerDocsRoute(server, registry, binStore))\n      pending.push(registerDocsDeleteRoute(server, registry))\n      pending.push(registerAssemblyRoute(server, registry))\n      pending.push(registerFeatureTreeRoute(server, registry))\n    } catch (error) {\n      // Roll back the partial batch, or the next attempt trips the duplicate\n      // guard on the routes that did register.\n      for (const dispose of pending) dispose()\n      throw error\n    }\n    routeDisposers = pending\n    return '/dsh-cad/scene'\n  }\n\n  // The demo route backs the CAD editor's startup fetch (before any tool\n  // call), so registration must not wait for the first tool use. The web\n  // composition may provide the HTTP server after our activation, so retry\n  // briefly; fiber ordering decides the exact moment.\n  let attempts = 0\n  const retry = setInterval(() => {\n    if (routeDisposers.length > 0 || ++attempts > 200) {\n      clearInterval(retry)\n      return\n    }\n    try {\n      ensureSceneRoute()\n    } catch {\n      /* the lazy path (first tool use) still covers late availability */\n    }\n  }, 100)\n  try {\n    ensureSceneRoute()\n  } catch {\n    /* registers lazily at first tool use */\n  }\n\n  const cadView = createCadViewTool({ store, workspaceRoot, ensureSceneRoute })\n  const cadInfo = createCadInfoTool({ workspaceRoot })\n  const modelTools = createModelTools({ store: binStore, sceneStore: store, workspaceRoot, ensureSceneRoute, registry })\n  const cadFreeCad = createFreeCadTool({ store: binStore, workspaceRoot, ensureSceneRoute })\n  const cadFusion = createFusionTool({ store: binStore, workspaceRoot, ensureSceneRoute })\n  const cadOnshape = createOnshapeTool({ store: binStore, workspaceRoot, ensureSceneRoute })\n  const cadImage = createCadImageTool({ store, workspaceRoot, ensureSceneRoute })\n  const cadScript = createCadScriptTool({ workspaceRoot })\n\n  const disposers = [\n    ctx.tools.register(cadView),\n    ctx.tools.register(cadInfo),\n    ...modelTools.map((tool) => ctx.tools.register(tool)),\n    ctx.tools.register(cadFreeCad),\n    ctx.tools.register(cadFusion),\n    ctx.tools.register(cadOnshape),\n    ctx.tools.register(cadImage),\n    ctx.tools.register(cadScript),\n  ]\n\n  ctx.effect(() => {\n    return () => {\n      clearInterval(retry)\n      for (const dispose of disposers) dispose()\n      for (const dispose of routeDisposers) dispose()\n      routeDisposers = []\n    }\n  })\n}\n"
    },
    {
      "path": "src/routes.ts",
      "content": "/**\n * Same-origin scene routes:\n * - GET /dsh-cad/scene/<viewId>  — JSON scenes (cad_view files)\n * - GET /dsh-cad/bin/<viewId>    — packed binary scenes (modeling document)\n * - GET /dsh-cad/demo-scene      — the built-in demo example, parsed from the\n *                                  packaged demo-bracket.brep by OCCT (local\n *                                  file ↔ editor display correspondence)\n * - GET /dsh-cad/docs            — the workspace document file space (list)\n * - POST /dsh-cad/docs/delete    — remove a document (panel delete button)\n */\nimport { createHash } from 'node:crypto'\nimport { readFile } from 'node:fs/promises'\nimport type { IncomingMessage, ServerResponse } from 'node:http'\nimport type { SceneStore } from './store.js'\nimport type { BinarySceneStore } from './modeling/bin-store.js'\nimport type { DocumentRegistry } from './modeling/registry.js'\nimport { assemblyTreePayload } from './modeling/assembly.js'\nimport { featureTreePayload } from './modeling/feature-tree.js'\nimport { convert } from './convert/index.js'\n\nexport const SCENE_ROUTE_PATH = '/dsh-cad/scene'\nexport const BIN_ROUTE_PATH = '/dsh-cad/bin'\nexport const DEMO_SCENE_ROUTE_PATH = '/dsh-cad/demo-scene'\nexport const DOCS_ROUTE_PATH = '/dsh-cad/docs'\nexport const DOCS_DELETE_ROUTE_PATH = '/dsh-cad/docs/delete'\nexport const ASSEMBLY_ROUTE_PATH = '/dsh-cad/asm'\nexport const FEATURE_TREE_ROUTE_PATH = '/dsh-cad/tree'\n\n/** The built-in demo examples (packaged as lib/demo-<part>.brep). */\nexport const DEMO_PARTS = ['bracket', 'flange', 'shaft'] as const\nexport type DemoPart = (typeof DEMO_PARTS)[number]\n\n/** Register the scene route on the shared HTTP server. Returns a disposer. */\nexport function registerSceneRoute(server: { register: (route: SceneRoute) => () => void }, store: SceneStore): () => void {\n  return server.register({\n    kind: 'prefix',\n    path: SCENE_ROUTE_PATH,\n    handler: async (req: IncomingMessage, res: ServerResponse) => {\n      const url = new URL(req.url ?? '/', 'http://localhost')\n      const segments = url.pathname.split('/').filter((segment) => segment !== '')\n      // ['/dsh-cad', 'scene', '<viewId>'] → viewId is the 3rd segment.\n      const viewId = segments[2]\n      if (req.method !== 'GET' || viewId === undefined) {\n        res.writeHead(404, { 'content-type': 'application/json' })\n        res.end(JSON.stringify({ error: 'not found' }))\n        return\n      }\n      const scene = await store.get(viewId)\n      if (scene === null) {\n        res.writeHead(404, { 'content-type': 'application/json' })\n        res.end(JSON.stringify({ error: 'unknown scene' }))\n        return\n      }\n      const etag = store.etag(scene)\n      if (req.headers['if-none-match'] === etag) {\n        res.writeHead(304)\n        res.end()\n        return\n      }\n      const body = Buffer.from(JSON.stringify(scene))\n      res.writeHead(200, {\n        'content-type': 'application/json',\n        'content-length': body.length,\n        'cache-control': 'private, max-age=31536000, immutable',\n        etag,\n      })\n      res.end(body)\n    },\n  })\n}\n\ninterface SceneRoute {\n  kind: 'prefix' | 'exact'\n  path: string\n  handler: (req: IncomingMessage, res: ServerResponse) => void | Promise<void>\n}\n\n/** Register the binary scene route. Returns a disposer. */\nexport function registerBinRoute(server: { register: (route: SceneRoute) => () => void }, store: BinarySceneStore): () => void {\n  return server.register({\n    kind: 'prefix',\n    path: BIN_ROUTE_PATH,\n    handler: async (req: IncomingMessage, res: ServerResponse) => {\n      const url = new URL(req.url ?? '/', 'http://localhost')\n      const segments = url.pathname.split('/').filter((segment) => segment !== '')\n      // ['/dsh-cad', 'bin', '<viewId>'] → viewId is the 3rd segment.\n      const viewId = segments[2]\n      if (req.method !== 'GET' || viewId === undefined) {\n        res.writeHead(404, { 'content-type': 'application/json' })\n        res.end(JSON.stringify({ error: 'not found' }))\n        return\n      }\n      const entry = await store.get(viewId)\n      if (entry === null) {\n        res.writeHead(404, { 'content-type': 'application/json' })\n        res.end(JSON.stringify({ error: 'unknown scene' }))\n        return\n      }\n      if (req.headers['if-none-match'] === entry.etag) {\n        res.writeHead(304)\n        res.end()\n        return\n      }\n      res.writeHead(200, {\n        'content-type': 'application/octet-stream',\n        'content-length': entry.buffer.length,\n        'cache-control': 'no-store',\n        etag: entry.etag,\n      })\n      res.end(entry.buffer)\n    },\n  })\n}\n\n/** Parse a packaged demo BRep once per part (OCCT import worker), cached. */\nconst demoCache = new Map<string, Promise<{ body: Buffer; etag: string }>>()\n\nfunction loadDemoScene(part: string): Promise<{ body: Buffer; etag: string }> {\n  let entry = demoCache.get(part)\n  if (entry === undefined) {\n    entry = (async () => {\n      const brepPath = new URL(`./demo-${part}.brep`, import.meta.url)\n      const buffer = await readFile(brepPath)\n      const scene = await convert(buffer, 'brep', `demo-${part}`)\n      const body = Buffer.from(JSON.stringify(scene))\n      return { body, etag: `\"demo-${part}-${createHash('sha1').update(body).digest('hex')}\"` }\n    })()\n    demoCache.set(part, entry)\n    entry.catch(() => demoCache.delete(part))\n  }\n  return entry\n}\n\n/** Register the demo-scene route: GET /dsh-cad/demo-scene?part=<bracket|flange|shaft>. */\nexport function registerDemoRoute(server: { register: (route: SceneRoute) => () => void }): () => void {\n  return server.register({\n    kind: 'exact',\n    path: DEMO_SCENE_ROUTE_PATH,\n    handler: async (req: IncomingMessage, res: ServerResponse) => {\n      const url = new URL(req.url ?? '/', 'http://localhost')\n      const part = url.searchParams.get('part') ?? 'bracket'\n      if (req.method !== 'GET' || !(DEMO_PARTS as readonly string[]).includes(part)) {\n        res.writeHead(404, { 'content-type': 'application/json' })\n        res.end(JSON.stringify({ error: part === undefined ? 'not found' : `unknown demo part: ${part}` }))\n        return\n      }\n      try {\n        const cached = await loadDemoScene(part)\n        if (req.headers['if-none-match'] === cached.etag) {\n          res.writeHead(304)\n          res.end()\n          return\n        }\n        res.writeHead(200, {\n          'content-type': 'application/json',\n          'content-length': cached.body.length,\n          'cache-control': 'private, max-age=31536000, immutable',\n          etag: cached.etag,\n        })\n        res.end(cached.body)\n      } catch (cause: unknown) {\n        res.writeHead(500, { 'content-type': 'application/json' })\n        res.end(JSON.stringify({ error: cause instanceof Error ? cause.message : String(cause) }))\n      }\n    },\n  })\n}\n\n/** Register the docs file-space route: GET /dsh-cad/docs (list documents). */\nexport function registerDocsRoute(\n  server: { register: (route: SceneRoute) => () => void },\n  registry: DocumentRegistry,\n  binStore: BinarySceneStore,\n): () => void {\n  return server.register({\n    kind: 'exact',\n    path: DOCS_ROUTE_PATH,\n    handler: async (req: IncomingMessage, res: ServerResponse) => {\n      if (req.method !== 'GET') {\n        res.writeHead(404, { 'content-type': 'application/json' })\n        res.end(JSON.stringify({ error: 'not found' }))\n        return\n      }\n      try {\n        const docs = await registry.list()\n        const entries = await Promise.all(\n          docs.map(async (doc) => ({\n            id: doc.id,\n            name: doc.name,\n            bodies: doc.bodyCount,\n            updatedAt: doc.updatedAt,\n            // Op count: the panel's liveness signal. It polls this list and\n            // re-fetches the scene when the tracked document's version moves,\n            // so the viewport follows modeling ops even when the conversation\n            // meta pipeline is stale (host UI drift).\n            version: doc.opCount,\n            // Preview URL only when a published scene exists (memory or mirror).\n            ...(await binStore.has(doc.id) ? { sceneUrl: `${BIN_ROUTE_PATH}/${doc.id}` } : {}),\n          })),\n        )\n        // The panel's host-independent channel: with ?session=<id>, also\n        // report that session's bound (active) document and its versioned\n        // scene URL. The resident panel polls this when the conversation\n        // meta pipeline is unavailable (host version drift, cold start) —\n        // its own route keeps the Part tab live across host UI changes.\n        const sessionId = new URL(req.url ?? '/', 'http://localhost').searchParams.get('session')\n        let active: { id: string; name: string; version: number; sceneUrl?: string } | undefined\n        if (sessionId !== null) {\n          const bound = await registry.bindingOf(sessionId)\n          const doc = bound === null ? undefined : docs.find((entry) => entry.id === bound)\n          if (doc !== undefined) {\n            active = {\n              id: doc.id,\n              name: doc.name,\n              version: doc.opCount,\n              ...(await binStore.has(doc.id) ? { sceneUrl: `${BIN_ROUTE_PATH}/${doc.id}?v=${doc.opCount}` } : {}),\n            }\n          }\n        }\n        const body = Buffer.from(JSON.stringify({ docs: entries, ...(active !== undefined ? { active } : {}) }))\n        res.writeHead(200, {\n          'content-type': 'application/json',\n          'content-length': body.length,\n          'cache-control': 'no-store',\n        })\n        res.end(body)\n      } catch (cause: unknown) {\n        res.writeHead(500, { 'content-type': 'application/json' })\n        res.end(JSON.stringify({ error: cause instanceof Error ? cause.message : String(cause) }))\n      }\n    },\n  })\n}\n\n/** Register the docs delete route: POST /dsh-cad/docs/delete?id=<docId>. */\nexport function registerDocsDeleteRoute(\n  server: { register: (route: SceneRoute) => () => void },\n  registry: DocumentRegistry,\n): () => void {\n  return server.register({\n    kind: 'exact',\n    path: DOCS_DELETE_ROUTE_PATH,\n    handler: async (req: IncomingMessage, res: ServerResponse) => {\n      const url = new URL(req.url ?? '/', 'http://localhost')\n      const id = url.searchParams.get('id')\n      if (req.method !== 'POST' || id === null || id === '') {\n        res.writeHead(404, { 'content-type': 'application/json' })\n        res.end(JSON.stringify({ error: 'not found' }))\n        return\n      }\n      try {\n        const removed = await registry.remove(id)\n        if (!removed) {\n          res.writeHead(404, { 'content-type': 'application/json' })\n          res.end(JSON.stringify({ error: `unknown document: ${id}` }))\n          return\n        }\n        res.writeHead(200, { 'content-type': 'application/json', 'cache-control': 'no-store' })\n        res.end(JSON.stringify({ deleted: id }))\n      } catch (cause: unknown) {\n        res.writeHead(500, { 'content-type': 'application/json' })\n        res.end(JSON.stringify({ error: cause instanceof Error ? cause.message : String(cause) }))\n      }\n    },\n  })\n}\n\n/**\n * Register the assembly-tree route: GET /dsh-cad/asm/<docId> returns the\n * panel's PARTS + CONSTRAINTS data (instance names/colors, resolved\n * constraint rows), folded from the persisted op log — no worker round-trip,\n * so it keeps serving after restarts and for non-active documents.\n */\nexport function registerAssemblyRoute(\n  server: { register: (route: SceneRoute) => () => void },\n  registry: DocumentRegistry,\n): () => void {\n  return server.register({\n    kind: 'prefix',\n    path: ASSEMBLY_ROUTE_PATH,\n    handler: async (req: IncomingMessage, res: ServerResponse) => {\n      const url = new URL(req.url ?? '/', 'http://localhost')\n      const segments = url.pathname.split('/').filter((segment) => segment !== '')\n      // ['/dsh-cad', 'asm', '<docId>'] → docId is the 3rd segment.\n      const docId = segments[2]\n      if (req.method !== 'GET' || docId === undefined) {\n        res.writeHead(404, { 'content-type': 'application/json' })\n        res.end(JSON.stringify({ error: 'not found' }))\n        return\n      }\n      try {\n        const document = await registry.open(docId)\n        if (document === null) {\n          res.writeHead(404, { 'content-type': 'application/json' })\n          res.end(JSON.stringify({ error: `unknown document: ${docId}` }))\n          return\n        }\n        await document.restore()\n        const meta = await registry.resolve(docId)\n        const body = Buffer.from(\n          JSON.stringify({ ...(meta === null ? {} : { name: meta.name }), ...assemblyTreePayload(document.doc) }),\n        )\n        res.writeHead(200, {\n          'content-type': 'application/json',\n          'content-length': body.length,\n          'cache-control': 'no-store',\n        })\n        res.end(body)\n      } catch (cause: unknown) {\n        res.writeHead(500, { 'content-type': 'application/json' })\n        res.end(JSON.stringify({ error: cause instanceof Error ? cause.message : String(cause) }))\n      }\n    },\n  })\n}\n\nexport type { SceneRoute }\n\n/**\n * Register the feature-tree route: GET /dsh-cad/tree/<docId> returns the Part\n * tab's structure panel (sketches + features in op order), folded from the\n * persisted op log — no worker round-trip, so it keeps serving after restarts\n * and for non-active documents (same pattern as the assembly tree).\n */\nexport function registerFeatureTreeRoute(\n  server: { register: (route: SceneRoute) => () => void },\n  registry: DocumentRegistry,\n): () => void {\n  return server.register({\n    kind: 'prefix',\n    path: FEATURE_TREE_ROUTE_PATH,\n    handler: async (req: IncomingMessage, res: ServerResponse) => {\n      const url = new URL(req.url ?? '/', 'http://localhost')\n      const segments = url.pathname.split('/').filter((segment) => segment !== '')\n      // ['/dsh-cad', 'tree', '<docId>'] → docId is the 3rd segment.\n      const docId = segments[2]\n      if (req.method !== 'GET' || docId === undefined) {\n        res.writeHead(404, { 'content-type': 'application/json' })\n        res.end(JSON.stringify({ error: 'not found' }))\n        return\n      }\n      try {\n        const document = await registry.open(docId)\n        if (document === null) {\n          res.writeHead(404, { 'content-type': 'application/json' })\n          res.end(JSON.stringify({ error: `unknown document: ${docId}` }))\n          return\n        }\n        await document.restore()\n        const body = Buffer.from(JSON.stringify(featureTreePayload(document.doc)))\n        res.writeHead(200, {\n          'content-type': 'application/json',\n          'content-length': body.length,\n          'cache-control': 'no-store',\n        })\n        res.end(body)\n      } catch (cause: unknown) {\n        res.writeHead(500, { 'content-type': 'application/json' })\n        res.end(JSON.stringify({ error: cause instanceof Error ? cause.message : String(cause) }))\n      }\n    },\n  })\n}\n"
